function uniquePathsWithObstacles(obstacleGrid: number[][]): number {
  const m = obstacleGrid.length;
  const n = obstacleGrid[0].length;
  // dp[j] — число путей до клетки (i, j) текущей строки.
  // Перед обновлением dp[j] хранит число путей до клетки сверху.
  const dp: number[] = new Array(n).fill(0);
  // Фиктивный «вход» в стартовую клетку: если она свободна, путей туда 1
  dp[0] = 1;

  for (let i = 0; i < m; i++) {
    for (let j = 0; j < n; j++) {
      if (obstacleGrid[i][j] === 1) {
        // Через препятствие пройти нельзя — путей ноль
        dp[j] = 0;
      } else if (j > 0) {
        // Пути сверху (старое dp[j]) + пути слева (новое dp[j - 1])
        dp[j] += dp[j - 1];
      }
      // При j === 0 приходим только сверху: dp[0] остаётся как есть
    }
  }

  return dp[n - 1];
}

// Время: O(m · n)
// Память: O(n) — одна строка dp
